# Số liệu minh hoạ: 2 loại điều trị, 2 nhóm bệnh nhân (nhẹ / nặng)
#              (khỏi, tổng)
A = {"nhẹ": (81, 87),  "nặng": (192, 263)}
B = {"nhẹ": (234, 270), "nặng": (55, 80)}

def rate(d): return sum(k for k, n in d.values()) / sum(n for k, n in d.values())

for g in ("nhẹ", "nặng"):
    a, b = A[g], B[g]
    print(g, "A:", round(a[0]/a[1], 3), " B:", round(b[0]/b[1], 3))
print("gộp  A:", round(rate(A), 3), " B:", round(rate(B), 3))

