A = {'nhe': (81, 87), 'nang': (192, 263)}
B = {'nhe': (234, 270), 'nang': (55, 80)}
r = lambda t: t[0] / t[1]
rate = lambda d: sum(k for k, n in d.values()) / sum(n for k, n in d.values())
print('A better in every group' if all(r(A[g]) > r(B[g]) for g in A) else 'other')
print('B better overall' if rate(B) > rate(A) else 'other')
